import { mkdirSync, writeFileSync } from "node:fs";
import { dirname, join } from "node:path";
import { fileURLToPath } from "node:url";

const root = join(dirname(fileURLToPath(import.meta.url)), "..");
const outDir = join(root, "sample-data", "averly-services-group");
mkdirSync(outDir, { recursive: true });
const organisationLabel = "Averly Services Group";
const anchor = new Date("2026-08-07T12:00:00.000Z");
const date = (days, hour = 10) => {
  const d = new Date(anchor);
  d.setUTCDate(d.getUTCDate() - days);
  d.setUTCHours(hour, 0, 0, 0);
  return d.toISOString();
};
const day = (days) => date(days).slice(0, 10);
const titleCase = (value) => value.replace(/_/g, " ").replace(/\b\w/g, (letter) => letter.toUpperCase());
const lowerFirst = (value) => value.charAt(0).toLowerCase() + value.slice(1);
const upperFirst = (value) => value.charAt(0).toUpperCase() + value.slice(1);
const write = (name, value) => writeFileSync(join(outDir, name), `${JSON.stringify(value, null, 2)}\n`);

