const composeSummary = (person, blueprint, index) => {
  const order = person.voice.orders[index % person.voice.orders.length];
  return order
    .map((key) => {
      if (key === "action") return `${person.voice.actionLead[index % person.voice.actionLead.length]} ${lowerFirst(blueprint.action)}.`;
      if (key === "close") return `${person.voice.closeLead[index % person.voice.closeLead.length]} ${lowerFirst(blueprint.nextFocus)}.`;
      if (/^i[0-2]$/.test(key)) return blueprint.insights[Number(key.slice(1))];
      return blueprint[key];
    })
    .join(" ");
};

const relationships = people.map((person) => ({
  key: person.key,
  identityMode: person.confidential ? "confidential" : "standard",
  name: person.confidential ? person.displayLabel : person.name,
  displayLabel: person.displayLabel ?? person.name,
  role: person.role,
  organisationLabel,
  email: person.confidential ? "" : `${person.name.toLowerCase().replace(" ", ".")}.sample@averly.example`,
  currentFocus: person.focus,
  aiNameAllowed: !person.confidential,
  themes: person.themes,
}));
const assignments = people.map(({ key }) => ({ relationshipKey: key, assignmentRole: "primary", assignee: "installing_user" }));
const categoryCycle = ["recurring_theme", "strength", "development_opportunity", "behaviour_pattern", "goal", "recurring_theme"];
const sessions = [], actions = [], developmentUpdates = [], intelligenceItems = [];

for (const [personIndex, person] of people.entries()) {
  const label = person.displayLabel ?? person.name;
  for (const [i, b] of person.sessions.entries()) {
    const daysAgo = 181 - i * 35 - (personIndex % 5);
    const sessionKey = `${person.key}-session-${i + 1}`;
    const theme = person.themes[i % person.themes.length];
    const summary = composeSummary(person, b, i);
    sessions.push({
      key: sessionKey, relationshipKey: person.key, sessionNumber: i + 1, sessionDate: day(daysAgo),
      displayDate: day(daysAgo), displayTime: i % 2 ? "14:30" : "10:00", startsAt: date(daysAgo, i % 2 ? 14 : 10),
      status: "completed", title: b.type, durationMinutes: 60, focus: b.focus, preparation: b.prep,
      notes: b.notes, privateNotes: "", summary, aiSummaryApproved: true, completedAt: date(daysAgo, i % 2 ? 15 : 11),
      emergingThemes: `${b.insights[0]}\n\n${b.insights[1]}\n\n${b.insights[2]}`,
      strengthsObserved: b.strength,
      valuesBecomingVisible: b.context,
      professionalIdentityDevelopment: b.evidence,
      agreedActions: b.action, suggestedFocus: b.nextFocus,
      coachReflection: b.reflection,
      themeKeys: person.themes,
    });
    actions.push({
      key: `${person.key}-action-${i + 1}`, relationshipKey: person.key, sessionKey, title: b.action,
      notes: b.incident, owner: label, status: b.actionStatus ?? "Completed",
      due: day(Math.max(daysAgo - 12, 1)), themeKey: theme,
    });
    intelligenceItems.push({
      key: `${person.key}-intel-${i + 1}`, relationshipKey: person.key, sessionKey, category: categoryCycle[i],
      title: `${titleCase(theme)}: ${b.focus}`,
      description: `${b.incident} ${b.insights[1]} In this conversation ${label} ${person.stages[i]}.`,
      status: "approved", confidenceScore: 56 + i * 7, confidenceLabel: i < 2 ? "emerging" : i < 4 ? "supported" : "strongly supported",
      sourceType: "coach_observation", firstIdentifiedAt: date(daysAgo + 1, 9), approvedAt: date(daysAgo, 12), themeKey: theme,
      evidenceText: `${b.happened} ${b.insights[0]}`,
    });
    if (i === 1 || i === 4) {
      const status = i === 1 ? "emerging" : "supported";
      developmentUpdates.push({
        key: `${person.key}-update-${i === 1 ? 1 : 2}`, relationshipKey: person.key, sessionKey, status: "applied",
        conversationSummary: `${b.happened} ${b.changed}`, hasMeaningfulChanges: true,
        proposedChanges: {
          currentFocus: { action: "replace", value: person.focus, reason: `${upperFirst(person.progress)}.` },
          strengths: { add: [{ value: b.strength, status, reason: b.incident }] },
          emergingThemes: { add: [{ value: `${titleCase(theme)}: ${b.focus}`, status, reason: b.insights[0] }] },
          growthAreas: { add: [{ value: b.unresolved, status, reason: b.insights[1] }] },
          coachingPreferences: { add: [{ value: b.preference, status, reason: b.context }] },
          patterns: { add: [{ value: b.insights[2], status, reason: b.changed }] },
        },
        evidenceSummary: [{ changeKey: "strengths", evidenceText: b.evidence, sourceExcerpt: b.incident }],
        coachNote: b.reflection,
        generatedAt: date(daysAgo - 1, 16), reviewedAt: date(daysAgo - 1, 17), appliedAt: date(daysAgo - 1, 18),
      });
    }
  }
}

