const countCheck = { relationships: relationships.length, sessions: sessions.length, actions: actions.length, developmentUpdates: developmentUpdates.length, intelligenceItems: intelligenceItems.length, confidential: relationships.filter((r) => r.identityMode === "confidential").length };
console.log(JSON.stringify({ outDir, ...countCheck }, null, 2));

const problems = [];
const expected = { relationships: 12, sessions: 72, actions: 72, developmentUpdates: 24, intelligenceItems: 72 };
for (const [name, count] of Object.entries(expected)) {
  if (countCheck[name] !== count) problems.push(`COUNT ${name}: expected ${count}, received ${countCheck[name]}`);
}
for (const session of sessions) {
  const words = session.summary.trim().split(/\s+/).length;
  if (words < 150 || words > 220) problems.push(`WORDS ${session.key}: ${words} (expected 150-220)`);
}
const gramIndex = new Map();
for (const session of sessions) {
  const words = session.summary.toLowerCase().replace(/[^a-z0-9\s]/g, " ").split(/\s+/).filter(Boolean);
  const seen = new Set();
  for (let n = 0; n + 12 <= words.length; n += 1) {
    const gram = words.slice(n, n + 12).join(" ");
    if (seen.has(gram)) continue;
    seen.add(gram);
    const owner = gramIndex.get(gram);
    if (owner) problems.push(`REPEAT 12-gram shared by ${owner} and ${session.key}: "${gram}"`);
    else gramIndex.set(gram, session.key);
  }
}
if (problems.length) {
  for (const problem of problems.slice(0, 40)) console.error(problem);
  console.error(`${problems.length} validation problem(s)`);
  process.exitCode = 1;
} else {
  console.log("Validation passed: counts, summary length (150-220 words) and no repeated 12-word phrase across summaries.");
}
